() => {
  const el = document.querySelector('[data-ref="e12"]') || null;
  // find the pricing card containing "Pro"
  const h = [...document.querySelectorAll('h2')].find(e=>e.textContent.trim()==='Pro');
  const card = h ? h.closest('div') : null;
  // go up to the card container
  let node = h;
  while(node && !node.className.includes('rounded') && node.parentElement){ node = node.parentElement; }
  return {found: !!card, className: node ? node.className : null, tag: node? node.tagName:null};
}

